// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _test(address player, uint256 potBefore, uint256 bankBefore) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(player != address(0) && player != address(c) && c.bank() != player);
        vm.assume(potBefore == c.pot());
        vm.assume(bankBefore == address(c).balance);
        try c.play{value: 10}() {} catch { return; }
        assertTrue(address(c).balance == c.pot() + bankBefore);
    }

    function testFuzz_test(address player, uint256 potBefore, uint256 bankBefore) public {
        _test(player, potBefore, bankBefore);
    }

    receive() external payable {}
}
